namespace PlayerOne.Windows;public partial class PlaylistEditDialog:System.Windows.Window{readonly string type;public string PlaylistName=>NameBox.Text;public string Url=>UrlBox.Text;public string Host=>HostBox.Text;public string Username=>UserBox.Text;public string Password=>PassBox.Password;public PlaylistEditDialog(string t){InitializeComponent();type=t;UrlBox.Visibility=t=="M3U"?Visibility.Visible:Visibility.Collapsed;HostBox.Visibility=UserBox.Visibility=PassBox.Visibility=t=="Xtream"?Visibility.Visible:Visibility.Collapsed;}public void SetM3u(string name,string url){NameBox.Text=name;UrlBox.Text=url;}public void SetXtream(string name,string host,string user,string pass){NameBox.Text=name;HostBox.Text=host;UserBox.Text=user;PassBox.Password=pass;}void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(NameBox.Text))NameBox.Text=type=="M3U"?"My Playlist":"Xtream";DialogResult=true;}}